import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getLatestMovies } from '../api/tmdb';

function MovieList() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchMovies = async () => {
      setLoading(true);
      const data = await getLatestMovies();
      setMovies(data);
      setLoading(false);
    };
    fetchMovies();
  }, []);

  if (loading) {
    return (
      <div className="w-full min-h-screen bg-[#0b090e] flex items-center justify-center text-white">
        <p className="text-sm font-bold animate-pulse text-purple-400">영화 목록을 불러오는 중...</p>
      </div>
    );
  }

  return (
    <div className="w-full min-h-screen bg-[#0b090e] text-white font-sans pb-24">
      
      {/* 상단 네비게이션 서브 탭 영역 */}
      <div className="max-w-6xl mx-auto px-4 pt-6 pb-4 border-b border-white/10">
        <h2 className="text-xl font-bold mb-4">전체영화</h2>
        <div className="flex gap-6 text-xs font-semibold text-zinc-400 border-b border-white/5 pb-2">
          <span className="text-white border-b-2 border-purple-500 pb-2 cursor-pointer">박스오피스</span>
          <span className="cursor-pointer hover:text-white transition">상영예정작</span>
          <span className="cursor-pointer hover:text-white transition">MEGA ONLY</span>
          <span className="cursor-pointer hover:text-white transition">필름소사이어티</span>
          <span className="cursor-pointer hover:text-white transition">클래식소사이어티</span>
        </div>
      </div>

      {/* 영화 카드 그리드 목록 영역 */}
      <div className="max-w-6xl mx-auto px-4 mt-8">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-6">
          {movies.map((movie, index) => {
            const posterUrl = movie.poster_path 
              ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` 
              : "https://via.placeholder.com/300x450?text=No+Image";

            const numericId = movie.id || index + 1;
            const bookingRate = ((numericId % 15) + 3.2).toFixed(1);
            const releaseDate = movie.release_date || '2026.08.05';

            return (
              <div 
                key={numericId} 
                className="flex flex-col group cursor-pointer"
                onClick={() => navigate(`/movie/${numericId}`)}
              >
                {/* 포스터 카드 박스 */}
                <div className="relative w-full h-[320px] rounded-xl overflow-hidden bg-zinc-900 border border-white/10 shadow-lg">
                  {/* 순위 배지 */}
                  <span className="absolute top-2 left-2 z-10 bg-black/60 backdrop-blur-md text-white text-xs font-black px-2.5 py-1 rounded-md border border-white/15">
                    {index + 1}
                  </span>
                  
                  <img 
                    src={posterUrl} 
                    alt={movie.title} 
                    className="w-full h-full object-cover group-hover:scale-105 transition duration-500" 
                  />
                </div>

                {/* 영화 정보 및 예매 버튼 */}
                <div className="mt-2.5 space-y-1">
                  <h3 className="text-sm font-bold text-zinc-100 truncate">
                    {movie.title || movie.name}
                  </h3>
                  
                  <p className="text-[11px] text-zinc-400">
                    예매율 {bookingRate}% &bull; 개봉일 {releaseDate}
                  </p>

                  <div className="pt-1">
                    <button 
                      onClick={(e) => {
                        e.stopPropagation(); // 카드 전체 클릭 이벤트와 충돌 방지
                        navigate(`/movie/${numericId}`);
                      }}
                      className="w-full py-2 bg-purple-700 hover:bg-purple-600 text-white rounded-lg text-xs font-bold transition shadow-md"
                    >
                      예매
                    </button>
                  </div>
                </div>

              </div>
            );
          })}
        </div>
      </div>

    </div>
  );
}

export default MovieList;
